def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    original = {"id": "b", "day": 9, "flagged": True}
    replacement = {"id": "b", "day": 2, "flagged": False}
    same_day = {"id": "a", "day": 2, "flagged": True}
    earlier_day = {"id": "c", "day": 1, "flagged": True}
    assert dedupe_transcripts([original, same_day, earlier_day, replacement]) == [
        earlier_day,
        same_day,
        replacement,
    ]


